<script setup>
import { ChevronLeft, ChevronRight } from 'lucide-vue-next'; import { computed } from 'vue'; const props = defineProps({ page: { type: Number, default: 1 }, total: { type: Number, default: 0 }, perPage: { type: Number, default: 10 } }); const emit = defineEmits(['change']); const totalPages = computed(() => Math.max(1, Math.ceil(props.total / props.perPage))); const pages = computed(() => Array.from({ length: Math.min(totalPages.value, 5) }, (_, index) => index + 1)); const from = computed(() => props.total ? (props.page - 1) * props.perPage + 1 : 0); const to = computed(() => Math.min(props.page * props.perPage, props.total));
</script>
<template><div class="flex items-center justify-between border-t border-[#E2E6EC] px-4 py-3"><span class="text-xs text-[#667085]">Menampilkan {{ from }}–{{ to }} dari {{ total }} data</span><div class="flex items-center gap-1"><button aria-label="Halaman sebelumnya" :disabled="page === 1" class="rounded p-1.5 text-[#667085] hover:bg-gray-100 disabled:cursor-not-allowed disabled:opacity-40" @click="emit('change', page - 1)"><ChevronLeft :size="14" /></button><button v-for="item in pages" :key="item" :aria-label="`Halaman ${item}`" :class="['h-7 w-7 rounded text-xs', item === page ? 'bg-[#173B6C] text-white' : 'text-[#667085] hover:bg-gray-100']" @click="emit('change', item)">{{ item }}</button><button aria-label="Halaman berikutnya" :disabled="page === totalPages" class="rounded p-1.5 text-[#667085] hover:bg-gray-100 disabled:cursor-not-allowed disabled:opacity-40" @click="emit('change', page + 1)"><ChevronRight :size="14" /></button></div></div></template>
